package java.util;
public final class UUID implements java.io.Serializable,Comparable<UUID> {private final long most,least;public UUID(long mostSigBits,long leastSigBits){most=mostSigBits;least=leastSigBits;}public static UUID randomUUID(){Random r=new Random();return new UUID((r.nextLong()&0xffffffffffff0fffL)|0x4000L,(r.nextLong()&0x3fffffffffffffffL)|0x8000000000000000L);}public static UUID fromString(String name){String[] p=name.split("-");if(p.length!=5)throw new IllegalArgumentException("Invalid UUID string: "+name);long a=Long.parseLong(p[0],16),b=Long.parseLong(p[1],16),c=Long.parseLong(p[2],16),d=Long.parseLong(p[3],16),e=Long.parseLong(p[4],16);return new UUID((a<<32)|(b<<16)|c,(d<<48)|e);}public long getMostSignificantBits(){return most;}public long getLeastSignificantBits(){return least;}public int version(){return (int)((most>>>12)&15);}public int variant(){return (int)((least>>> (64-(least>>>62))) & (least>>63));}private static String digits(long x,int n){long hi=1L<<(n*4);return Long.toHexString(hi|(x&(hi-1))).substring(1);}public String toString(){return digits(most>>32,8)+"-"+digits(most>>16,4)+"-"+digits(most,4)+"-"+digits(least>>48,4)+"-"+digits(least,12);}public boolean equals(Object o){return o instanceof UUID&&((UUID)o).most==most&&((UUID)o).least==least;}public int hashCode(){long x=most^least;return (int)(x^(x>>>32));}public int compareTo(UUID u){return most<u.most?-1:most>u.most?1:least<u.least?-1:least>u.least?1:0;}}
